-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ptBR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.shaman.elemental.Name"] = "Elemental"
L["rm.era.shaman.elemental.Description"] = "Elemental a partir do nível 10 (a maioria dos pontos em Elemental); montada a partir da Icy Veins e Wowhead. Choque Terreno interrompe e finaliza um alvo prestes a morrer. Em movimento: Choque Flamejante, senão Choque Gélido. Solo com o alvo corpo a corpo: Choque Terreno acima de 30% de vida, depois corpo a corpo. Contra três ou mais inimigos: Totem de Nova de Fogo e Totem de Magma quando você estiver corpo a corpo, e Cadeia de Raios. Cadeia de Raios sob Mestre dos Elementos ou Abstração, senão Raio. Lembretes: Escudo de Raios, Trinca-pedra fora de raides, Calcinante ou Magma, Fonte de Mana ou Torrente Curativa, Mestre dos Elementos com Cadeia de Raios pronta, Rapidez da Natureza e Onda Curativa abaixo de 30%, cura depois de uma puxada. Dissipações, expurgos e o uso de graus inferiores ficam com você."
L["rm.era.shaman.elemental.simulator.Name"] = "Elemental, Cadeia de Raios assim que sair da recarga (simulador)"
L["rm.era.shaman.elemental.simulator.Description"] = "A lista Elemental do simulador, uma alternativa à rotação integrada de Elemental recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Cadeia de Raios assim que sair do tempo de recarga, mesmo contra um alvo, Choque Terreno enquanto Mestre dos Elementos estiver ativo, senão Raio. Mais rápida, mas muito mais faminta por mana que a rotação integrada recomendada; a mesma interrupção, os mesmos totens e lembretes."
L["rm.era.shaman.enhancement.Name"] = "Aperfeiçoamento"
L["rm.era.shaman.enhancement.Description"] = "Níveis 1–60, também em reinos Hardcore e Autossuficientes, e todo Xamã sem maioria de talentos; montada a partir da Icy Veins, Wowhead e simulador. Raio puxa à distância; Choque Terreno interrompe. Em raides, só Ataque da Tempestade e Choque Gélido (espaços de penalidade). Contra três ou mais inimigos lutando com você, Totem de Nova de Fogo e Totem de Magma. Depois Ataque da Tempestade, Choque Terreno na penalidade do Ataque da Tempestade ou para finalizar, Choque Flamejante quando ele for durar até o fim, Choque Terreno enquanto você tiver metade da sua mana, e Raio enquanto estiver fora de alcance. Lembretes: Trinca-pedra solo e Arma de Fúria dos Ventos em masmorras, Escudo de Raios, Força da Terra, Calcinante, Fúria dos Ventos ou Graça do Ar, Fonte de Mana ou Torrente Curativa, cura depois de uma puxada e em emergências. Garra de Pedra, Prisão Terrena, alternância de totens e habilidades raciais vêm listados como desativados; dissipações, expurgos e totens purificadores ficam com você."
L["rm.era.shaman.enhancement.warcrafttavern.Name"] = "Aperfeiçoamento, Choque Flamejante primeiro (Warcraft Tavern)"
L["rm.era.shaman.enhancement.warcrafttavern.Description"] = "O Aperfeiçoamento da Warcraft Tavern, uma alternativa à rotação integrada de Aperfeiçoamento recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Arma de Fúria dos Ventos assim que você a aprende, Ataque da Tempestade, Choque Flamejante antes de qualquer choque direto, depois Choque Terreno enquanto sua ameaça estiver baixa, ou Choque Gélido em grupo quando ela estiver alta; Magma e Cadeia de Raios em grupos de inimigos. Os mesmos totens e lembretes da rotação integrada recomendada."
L["rm.era.shaman.restoration.Name"] = "Restauração"
L["rm.era.shaman.restoration.Description"] = "Restauração a partir do nível 10 (a maioria dos pontos em Restauração); montada a partir da Icy Veins e Wowhead. No seu alvo amigável: Onda Curativa sob Rapidez da Natureza, Rapidez da Natureza abaixo de 30%, Onda Curativa Menor abaixo de 40%, Curar Veneno ou Curar Doença, Cura Encadeada quando três membros do grupo perto de você estiverem abaixo de 85%, senão Onda Curativa abaixo de 90%. Em um inimigo que você combate: interrupção com Choque Terreno, Cadeia de Raios em grupos de inimigos, Choque Flamejante, Raio à distância, corpo a corpo. Lembretes: Escudo de Raios e Trinca-pedra quando solo, Vagalhão de Mana em grupo, Fonte de Mana, Força da Terra, Calcinante. A escolha de quem curar, o uso de graus inferiores e os totens Sísmico ou purificadores ficam com você; manter Caminho da Cura no tanque vem listado como desativado."
L["rm.era.shaman.restoration.warcrafttavern.Name"] = "Restauração, Cura Encadeada primeiro (Warcraft Tavern)"
L["rm.era.shaman.restoration.warcrafttavern.Description"] = "A Restauração da Warcraft Tavern, uma alternativa à rotação integrada de Restauração recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Cura Encadeada é a cura para qualquer um abaixo de 90%, com Onda Curativa Menor para quem estiver prestes a morrer; Onda Curativa é só para um curador designado ao tanque com Caminho da Cura (listado como desativado). As mesmas remoções de veneno e doença, o mesmo dano em inimigos e os mesmos lembretes de totens da rotação integrada recomendada."
L["rm.forever.shaman.elemental.Name"] = "Elemental"
L["rm.forever.shaman.elemental.Description"] = "Elemental à distância assim que Elemental é sua árvore de talentos principal com 21 pontos (o nível do Estouro de Lava), segundo a Icy Veins (antes disso, a rotação integrada de Aperfeiçoamento joga o híbrido corpo a corpo que todos os guias recomendam). Puxa com Raio (Cadeia de Raios em um grupo de inimigos), lança só instantâneos em movimento, usa Nova de Fogo e Cadeia de Raios em três ou mais inimigos, mantém Choque Flamejante ativo, Estouro de Lava sempre que sair do tempo de recarga, Ataque da Tempestade e Choque Terreno se você conhece Ataque da Tempestade, Nova de Fogo com Abstração em grupo, depois Raio. Lembretes: escudo, encantamento de arma, Totem Calcinante ou Totem de Magma, totens de grupo, Mestre dos Elementos, interrupção. A vida e a mana ficam ocultas dos addons no Forever, então se curar e pausar para recuperar mana são decisões suas. Fica com você: kiting com Totem de Prisão Terrena, Choque Gélido, Expurgar e outros totens."
L["rm.forever.shaman.enhancement.Name"] = "Aperfeiçoamento (Icy Veins)"
L["rm.forever.shaman.enhancement.Description"] = "Aperfeiçoamento corpo a corpo do nível 1 ao 60, e o padrão para qualquer Xamã antes de Estouro de Lava ou Totem de Vagalhão de Mana. Puxa com Raio à distância, depois Ataque da Tempestade sempre que sair do tempo de recarga, um Raio instantâneo com cinco acúmulos de Arma da Voragem, Nova de Fogo (com um totem de Fogo colocado) e Choque Flamejante em três ou mais inimigos, Choque Terreno sobre a penalidade do Ataque da Tempestade, Choque Flamejante em grupo, e Choque Terreno sempre que sair do tempo de recarga; Raio preenche a lacuna enquanto o alvo está fora de alcance. A vida e a mana ficam ocultas dos addons no Forever, então se curar e pausar para recuperar mana são decisões suas (a rotação integrada da Wowhead economiza mana em vez disso). Lembretes: encantamento de arma (Fúria dos Ventos, senão Labaredas, senão Trinca-pedra), Escudo de Água ou Escudo de Raios, a interrupção com Choque Terreno, Totem Calcinante ou Totem de Magma, totens de grupo, Fúria do Clarividente, Totem da Garra de Pedra. Fica com você: predefinições de totens, Choque Gélido, Expurgar e outros totens."
L["rm.forever.shaman.enhancement.wowhead.Name"] = "Aperfeiçoamento, econômico em mana (Wowhead)"
L["rm.forever.shaman.enhancement.wowhead.Description"] = "O Aperfeiçoamento econômico em mana da Wowhead e da Mobalytics: o ataque automático faz o trabalho, Ataque da Tempestade só enquanto a regeneração de mana do Ataque da Tempestade Aprimorado estiver inativa, nada de Choque Terreno na rotação (os choques servem para puxar e interromper) e, em grupo ou contra grupos de inimigos, Totem Calcinante com Nova de Fogo sempre que sair do tempo de recarga. Os mesmos lembretes de encantamento de arma, escudo e interrupção da rotação integrada da Icy Veins. Escolha esta em vez daquela rotação integrada se a mana acabar. Uma alternativa à rotação integrada de Aperfeiçoamento recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela."
L["rm.forever.shaman.restoration.Name"] = "Restauração"
L["rm.forever.shaman.restoration.Description"] = "Cura assim que Restauração é sua árvore de talentos principal com 16 pontos (o nível do Totem de Vagalhão de Mana), segundo a Icy Veins. Com um alvo amigável: uma Onda Curativa instantânea depois de usar Rapidez da Natureza, Curar Veneno e Curar Doença, Contracorrente em um alvo que não a tenha, Cura Encadeada em grupo, Onda Curativa. Você escolhe quem curar tomando-o como alvo; a vida e a mana ficam ocultas dos addons no Forever, então decidir quando usar Rapidez da Natureza e Onda Curativa Menor é com você. Com um alvo hostil e nada para curar: Nova de Fogo e Cadeia de Raios em grupos de inimigos, Ataque da Tempestade e Choque Terreno se você conhece Ataque da Tempestade, Choque Flamejante em elites e chefes, Raio e depois corpo a corpo. Lembretes: Escudo de Água, a interrupção com Choque Terreno, Vagalhão de Mana e os totens de bônus de grupo. Fica com você: graus inferiores, outros totens, Expurgar e Lobo Fantasma."
L["rm.mop.shaman.elemental.Name"] = "Recomendada"
L["rm.mop.shaman.elemental.Description"] = "Recomendada para Elemental a partir do nível 10, escolhida na especialização Elemental. A ordem da Wowhead: um Raio para abrir (Estouro de Lava com Fúria Liberada), Liberar Elementos com Fúria Liberada, Choque Flamejante quando estiver ausente ou prestes a acabar em um alvo que vá sobreviver, Estouro de Lava sobre Choque Flamejante (e a cada Torrente de Lava), Impacto Elemental, Choque Terreno com seis cargas de Escudo de Raios enquanto Choque Flamejante tiver 6 segundos restantes, Cadeia de Raios contra dois inimigos, Raio. Quatro ou mais inimigos em você: Magma corpo a corpo, Estouros de Lava gratuitos, Feixe de Lava durante Ascendência, Cadeia de Raios. Em movimento, mostra só instantâneos. Lembretes: Escudo de Raios, Labaredas, Totem Calcinante, Elemental do Fogo em elites e chefes, Mestre dos Elementos, Ascendência depois de um Estouro de Lava, Rapidez Ancestral, Açoite Trovejante e Sede de Sangue em grupo, Rajada de Vento, Tempestade Relampejante para mana, Fúria Xamanística e Transição Astral com pouca vida. Terremoto e Elemental da Terra vêm listados, mas desativados. Fica com você: Graça do Andarilho Espiritual, Choque Flamejante em alvos extras e onde ficar."
L["rm.mop.shaman.enhancement.Name"] = "Recomendada"
L["rm.mop.shaman.enhancement.Description"] = "Recomendada para Aperfeiçoamento a partir do nível 10, escolhida na especialização Aperfeiçoamento. A ordem da Wowhead: Liberar Elementos enquanto corre até o alvo, depois Liberar Elementos com Fúria Liberada, Impacto Elemental e Raio com cinco acúmulos de Arma da Voragem (ou intercalados com três quando seu próximo golpe estiver a mais de um segundo), Explosão Tormentosa durante Ascendência, Ataque da Tempestade (Golpe Primevo antes do nível 26), Açoite de Lava, Choque Flamejante sob Liberar Chama, Liberar Elementos, Choque Terreno. Dois ou mais inimigos em você: Cadeia de Raios em vez de Raio, Açoite de Lava para espalhar Choque Flamejante, Nova de Fogo a partir de quatro, Magma a partir de seis. Lembretes: Escudo de Raios, Fúria dos Ventos na mão principal e Labaredas na mão secundária, Totem Calcinante, Elemental do Fogo, Espírito Feral, Ascendência depois de Ataque da Tempestade, Mestre dos Elementos, Rapidez Ancestral, Açoite Trovejante e Sede de Sangue em grupo, Rajada de Vento, Fúria Xamanística e Transição Astral com pouca vida. Elemental da Terra vem listado, mas desativado."
L["rm.mop.shaman.enhancement.icyveins.Name"] = "Açoite de Lava primeiro (Icy Veins)"
L["rm.mop.shaman.enhancement.icyveins.Description"] = "Desativada por padrão; a mesma condição de troca da rotação integrada recomendada de Aperfeiçoamento, então ative esta e desative aquela para usá-la. A ordem da Icy Veins: Ataque da Tempestade, depois Açoite de Lava antes de gastar Arma da Voragem, Raio com cinco acúmulos ou a partir de três quando ele cair antes do seu próximo golpe, Liberar Elementos e depois Choque Flamejante, Choque Terreno. Contra quatro ou mais inimigos, espalha Choque Flamejante com Açoite de Lava e usa Nova de Fogo; Cadeia de Raios substitui Raio em grupos de inimigos. Fúria Xamanística é sugerida assim que sair do tempo de recarga em combate; os demais lembretes como na rotação integrada recomendada."
L["rm.mop.shaman.enhancement.simulator.Name"] = "Intercalar a cada acúmulo (simulador)"
L["rm.mop.shaman.enhancement.simulator.Description"] = "Desativada por padrão; a mesma condição de troca da rotação integrada recomendada de Aperfeiçoamento, então ative esta e desative aquela para usá-la. A lista do simulador para jogadores que sincronizam lançamentos entre golpes: Raio, Impacto Elemental ou Cadeia de Raios com qualquer número de acúmulos de Arma da Voragem sempre que o lançamento terminar antes do seu próximo golpe da mão principal, Liberar Elementos também sempre que Choque Flamejante estiver ausente, e Choque Terreno só abaixo de dois acúmulos. Lembretes como na rotação integrada recomendada."
L["rm.mop.shaman.restoration.Name"] = "Recomendada"
L["rm.mop.shaman.restoration.Description"] = "Recomendada para Restauração a partir do nível 10, escolhida na especialização Restauração. Cura seu alvo amigável (o Rotation Master não consegue escolher quem curar): Onda Curativa Maior sob Rapidez Ancestral, Maré Curativa abaixo de 35%, Purificar o Espírito contra Magia ou Maldições, Liberar Elementos e depois Chuva Curativa quando três aliados próximos estiverem feridos, Contracorrente, Cura Encadeada para dano no grupo, Onda Curativa Maior abaixo de 60%, Onda Curativa abaixo de 90%. Com um alvo atacável, causa dano em vez disso (Choque Flamejante, Estouro de Lava, Impacto Elemental, Raio). Lembretes: Escudo de Água, Terraviva, Escudo da Terra no seu foco, Torrente Curativa quando alguém estiver ferido, Vagalhão de Mana, Totem de Maré Curativa para dano pesado no grupo, Mestre dos Elementos ou Conselho dos Ancestrais, Rapidez Ancestral em um alvo com pouca vida, Graça do Andarilho Espiritual em movimento, Sede de Sangue, Rajada de Vento. Ascendência e Totem do Vínculo do Espírito vêm listados, mas desativados: use-os quando sua raide os designar."
L["rm.mop.shaman.restoration.hekili.Name"] = "Faixas de vida (Hekili)"
L["rm.mop.shaman.restoration.hekili.Description"] = "Desativada por padrão; a mesma condição de troca da rotação integrada recomendada de Restauração, então ative esta e desative aquela para usá-la. A lista do Hekili mantém Escudo da Terra e Contracorrente no seu alvo e Torrente Curativa e Chuva Curativa ativas sempre que estiverem inativas, depois cura pela vida média do seu grupo em até 40 metros: Cura Encadeada abaixo de 80%, Onda Curativa em um alvo abaixo de 70%, Onda Curativa Maior abaixo de 60%, Maré Curativa abaixo de 40%, com Totem de Maré Curativa, Conselho dos Ancestrais e Vagalhão de Mana nas mesmas faixas. Um alvo atacável recebe dano e Choque Terreno."
L["rm.mop.shaman.unspecialized.Name"] = "Sem especialização"
L["rm.mop.shaman.unspecialized.Description"] = "Para os níveis 1 a 9, e qualquer Xamã que ainda não escolheu uma especialização; cada rotação integrada de especialização assume assim que você escolhe uma. Raio para puxar à distância, Maré Curativa quando você está com pouca vida e sozinho, Golpe Primevo, Choque Terreno, e Raio enquanto estiver fora do alcance corpo a corpo. Mantém Escudo de Raios ativo."
L["rm.retail.shaman.elemental.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.shaman.elemental.Description"] = "Recomendada para Elemental no Midnight. Em combate, o jogo agora oculta Choque Flamejante, seus bônus, Voragem, tempos de recarga e vida para addons, então esta rotação mostra a própria sugestão do Assistente de Combate da Blizzard (a rotação de um botão), e para enquanto você lança ou não tem um inimigo como alvo. Lembretes do que ela deixa de fora: Ascendência, Elemental do Fogo ou Elemental da Tempestade e Rapidez da Natureza em combate, Graça do Andarilho Espiritual em movimento, Escudo de Raios e Fúria Celeste entre os combates (a sugestão da Blizzard mantém as imbuições da arma e do escudo), Rajada de Vento em um lançamento interrompível (só acende onde o jogo permite ler o lançamento), Transição Astral sempre que estiver pronta em combate (a vida fica oculta no Retail, então decidir quando usá-la é com você)."
L["rm.retail.shaman.elemental.icyveins.Name"] = "Referência (Icy Veins)"
L["rm.retail.shaman.elemental.icyveins.Description"] = "Apenas referência, desativada por padrão: a ordem da Icy Veins e do SimulationCraft lê Choque Flamejante, Mestre dos Elementos e Guardião da Tempestade, que o Midnight oculta em combate; a Voragem fica oculta no Retail, então os gastadores são usados pelo próprio custo em vez de perto da Voragem cheia. Guardião da Tempestade e Estouro de Lava antes da puxada. Contra três ou mais inimigos em combate: Guardião da Tempestade, Rapidez Ancestral, Choque Flamejante, Cadeia de Raios com Guardião da Tempestade, Impacto Elemental, Terremoto, Estouro de Lava com Torrente de Lava, Tormenta, Cadeia de Raios. Caso contrário, Guardião da Tempestade, Rapidez Ancestral, Choque Flamejante e Labareda Voltaica nos últimos 30% fora de Mestre dos Elementos, Estouro de Lava para ativá-lo, Tormenta e o Raio de Guardião da Tempestade dentro dele, Impacto Elemental ou Choque Terreno dentro dele, Labareda Voltaica, Tormenta, Choque Flamejante ou Choque Gélido em movimento, Impacto Elemental ou Choque Terreno sempre que você puder pagar por eles, Raio. Lembretes: Ascendência depois de usar Guardião da Tempestade, elementais, Graça do Andarilho Espiritual e os compartilhados."
L["rm.retail.shaman.enhancement.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.shaman.enhancement.Description"] = "Recomendada para Aperfeiçoamento no Midnight. Mostra a sugestão do Assistente de Combate da Blizzard (ela gasta Arma da Voragem, mantém Choque Flamejante e cuida de Totem de Irrupção e Cisão), e para enquanto você lança ou não tem um inimigo como alvo. Lembretes do que ela deixa de fora: Ascendência, Ventos da Perdição e Espírito Feral em combate, Escudo de Raios e Fúria Celeste entre os combates (a sugestão da Blizzard mantém Arma de Fúria dos Ventos), Rajada de Vento, Transição Astral."
L["rm.retail.shaman.enhancement.stormbringer.Name"] = "Referência de Traztormenta (SimulationCraft)"
L["rm.retail.shaman.enhancement.stormbringer.Description"] = "Apenas referência, desativada por padrão: a lista Traztormenta do SimulationCraft (a Icy Veins e a Wowhead concordam) lê Choque Flamejante, Raio Poderoso, Chamas Açoitantes e temporizadores de recarga, que o Midnight oculta em combate. Contra três ou mais inimigos em combate: Raio Poderoso pelo bônus, Tormenta com 10 acúmulos de Arma da Voragem, Cadeia de Raios com 9, Raio Poderoso, Açoite de Lava, Cisão. Depois, Tempestade Primordial com 9, Labareda Voltaica ou Choque Flamejante quando Choque Flamejante estiver ausente, Cisão, Raio Poderoso pelo bônus, Açoite de Lava para Chamas Açoitantes, Golpe de Vento, Tormenta ou Raio com 10 (8 com Labareda Voltaica ou Raio Poderoso quase prontos), Ataque da Tempestade com duas cargas, Açoite de Lava, Ataque da Tempestade, Labareda Voltaica, Raio Poderoso, Raio com 5, Choque Flamejante. Lembretes: Ventos da Perdição, Ascendência fora de Ventos da Perdição, Espírito Feral e os compartilhados."
L["rm.retail.shaman.enhancement.totemic.Name"] = "Referência de Totêmico (SimulationCraft)"
L["rm.retail.shaman.enhancement.totemic.Description"] = "Apenas referência, desativada por padrão: a lista Totêmico do SimulationCraft lê Choque Flamejante, Mão Quente, Fogo Giratório, Raio Poderoso e Ventos da Perdição, que o Midnight oculta em combate. Contra três ou mais inimigos em combate: Raio Poderoso, Cadeia de Raios com 5 acúmulos de Arma da Voragem. Depois, Labareda Voltaica ou Choque Flamejante quando Choque Flamejante estiver ausente, Totem de Irrupção, Cisão, Açoite de Lava com Mão Quente ou Fogo Giratório, Raio Poderoso pelo bônus, Tempestade Primordial com 10, Golpe de Vento, Raio Poderoso e Ataque da Tempestade durante Ventos da Perdição, Raio com 5, Raio Poderoso, Açoite de Lava, Ataque da Tempestade, Labareda Voltaica, Choque Flamejante. Os mesmos lembretes da referência Traztormenta."
L["rm.retail.shaman.initial.Name"] = "Assistente de Combate da Blizzard"
L["rm.retail.shaman.initial.Description"] = "Recomendada antes de você escolher uma especialização (enquanto o jogo informa a especialização inicial do Xamã). Destaca o feitiço que o Assistente de Combate da Blizzard sugere em seguida, a única orientação de rotação que o jogo ainda deixa um addon ler em combate no Midnight; aguarda enquanto você lança ou canaliza. Junto a isso, os lembretes que toda rotação integrada de Xamã compartilha, cada um assim que você conhece o feitiço dele. Quando você escolhe uma especialização no nível 10, as rotações integradas dessa especialização assumem."
L["rm.retail.shaman.restoration.Name"] = "Icy Veins"
L["rm.retail.shaman.restoration.Description"] = "Restauração no Midnight, como referência: o Assistente de Combate da Blizzard não cobre curadores, o jogo oculta a vida de todos em combate e o Rotation Master escolhe um feitiço, não um alvo, então esta rotação ordena suas ferramentas de cura pela disponibilidade em qualquer alvo que você selecionar e deixa com você a decisão de quem curar. Em um alvo amigável: Totem de Torrente Curativa, Liberar Vida, Chuva Curativa em grupo, Totem de Irrupção, Contracorrente, Cura Encadeada em grupo, Onda Curativa. Em um inimigo: Choque Flamejante quando ausente, Estouro de Lava, Raio. Lembretes: Escudo de Água, Escudo da Terra em um alvo amigável e Fúria Celeste entre os combates; Rapidez da Natureza em combate; Totem de Maré Curativa e Totem do Vínculo do Espírito em combate em grupo; Rajada de Vento; Transição Astral."
L["rm.sod.shaman.elemental.Name"] = "Elemental (SoD)"
L["rm.sod.shaman.elemental.Description"] = "Elemental da Temporada da Descoberta a partir do nível 10 (a maioria dos pontos em Elemental); montada a partir do simulador Fase 6, Wowhead e Icy Veins. Choque Terreno interrompe. Em movimento: Choque Flamejante, Choque Terreno com oito cargas de Escudo de Raios, Estouro de Lava ou Cadeia de Raios com uma ativação de Surto de Poder. Contra três ou mais inimigos: Choque Flamejante, Cadeia de Raios, Nova de Fogo, Estouro de Lava, Choque Terreno com oito cargas, Magma. Depois Estouro de Lava com Surto de Poder, Choque Flamejante mantido, Estouro de Lava enquanto seu Choque Flamejante durar, Choque Terreno com oito cargas, Cadeia de Raios contra dois inimigos, Raio. Lembretes: Labaredas para Queimadura, Escudo de Raios, Escudo da Terra em você mesmo, Espírito do Alfa, Espírito Feral, Fúria Xamanística, Mestre dos Elementos, totens. Berloques, Projeção Totêmica, dissipações e expurgos ficam com você."
L["rm.sod.shaman.enhancement.Name"] = "Aperfeiçoamento (SoD)"
L["rm.sod.shaman.enhancement.Description"] = "Temporada da Descoberta, níveis 1–60 com as runas conforme você as grava, duas armas ou arma de duas mãos, e todo Xamã da Temporada da Descoberta em que nenhuma outra rotação integrada se encaixe; montada a partir do simulador Fase 6, Icy Veins e Wowhead. Choque Flamejante puxa; Choque Terreno interrompe. Contra três ou mais inimigos: Magma, Nova de Fogo a partir de um totem de fogo, Cadeia de Raios com quatro acúmulos de Arma da Voragem, Choque Flamejante. Depois Estouro de Lava com cinco acúmulos de Arma da Voragem, Ataque da Tempestade, Açoite de Lava, Raio com cinco acúmulos, Choque Flamejante quando ele for durar, Choque Terreno, Impacto Derretido, Raio à distância. Lembretes: Arma de Fúria dos Ventos (Trinca-pedra antes), Labaredas em uma arma de mão secundária com Açoite de Lava (senão Fúria dos Ventos; nunca em um escudo; uma linha da Icy Veins com Fúria dos Ventos nas duas armas vem listada como desativada), Escudo de Água ou Escudo de Raios, Espírito do Alfa, Espírito Feral, Fúria Xamanística abaixo de 65% de mana, totens, Conselho dos Ancestrais. Projeção Totêmica, dissipações e expurgos ficam com você."
L["rm.sod.shaman.restoration.Name"] = "Restauração (SoD)"
L["rm.sod.shaman.restoration.Description"] = "Restauração da Temporada da Descoberta a partir do nível 10 (a maioria dos pontos em Restauração); montada a partir da Icy Veins e Wowhead. No seu alvo amigável: Contracorrente e depois Onda Curativa Menor abaixo de 40%, Curar Veneno ou Curar Doença, Chuva Curativa quando três membros do grupo perto de você estiverem abaixo de 85%, Cura Encadeada quando dois estiverem (na hora com uma ativação de Surto de Poder), Contracorrente abaixo de 95% para Mar Revolto, Onda Curativa abaixo de 90%. Em um inimigo, ataca. Lembretes: Escudo de Água (Escudo de Raios antes), Escudo da Terra no seu alvo amigável ou em você mesmo, Fúria Xamanística, Vagalhão de Mana, Fonte de Mana e Força da Terra. A escolha de quem curar e os totens Sísmico ou purificadores ficam com você."
L["rm.sod.shaman.tank.Name"] = "Tanque (SoD, Caminho Telúrico)"
L["rm.sod.shaman.tank.Description"] = "Tanque da Temporada da Descoberta, escolhida quando Caminho Telúrico está gravado; montada a partir da Icy Veins, Wowhead, simulador e Warcraft Tavern. Choque Flamejante puxa. Choque Terreno provoca um alvo corpo a corpo que não está atacando você, e interrompe. Contra dois ou mais inimigos: Impacto Derretido, Choque Flamejante, Cadeia de Raios com cinco acúmulos de Arma da Voragem ou com Surto de Poder, Nova de Fogo com cinco acúmulos. Depois Choque Flamejante mantido, Estouro de Lava com Surto de Poder ou enquanto Choque Flamejante durar, Ataque da Tempestade, Choque Terreno, Raio com cinco acúmulos, Impacto Derretido, Choque Gélido. Lembretes: Trinca-pedra, Escudo de Raios, Espírito do Alfa em você mesmo, Espírito Feral, Fúria Xamanística, Calcinante ou Magma, e totens de grupo."
L["rm.tbc.shaman.elemental.icyveins.Name"] = "Elemental (Icy Veins & simulador)"
L["rm.tbc.shaman.elemental.icyveins.Description"] = "Elemental lançador para a árvore de talentos Elemental. Raio é o preenchimento; Cadeia de Raios sai com Mestre dos Elementos, com Abstração enquanto você tiver 40% de mana, ou livremente acima de 80%; Choque Flamejante só em movimento; Choque Terreno interrompe; Nova de Fogo, Cadeia de Raios e Totem de Magma para grupos de inimigos. Antes de Cadeia de Raios, um alvo corpo a corpo fica com o ataque automático para poupar mana. Lembretes: Escudo de Água ou Escudo de Raios, um encantamento de arma, Totem da Ira (ou Totem Calcinante em lutas longas), Cólera dos Ares, Fonte de Mana, Chamado Totêmico após a luta, Mestre dos Elementos e Sede de Sangue/Heroísmo."
L["rm.tbc.shaman.elemental.nextaction.Name"] = "Elemental (NextActionTBC)"
L["rm.tbc.shaman.elemental.nextaction.Description"] = "O Elemental do NextActionTBC, uma alternativa à rotação integrada de Elemental da Icy Veins recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Mantém Choque Flamejante no alvo, Cadeia de Raios só contra dois ou mais inimigos enquanto a mana estiver acima de 30%, Raio nos demais casos. Lembra você de Escudo de Raios, um encantamento de arma, Mestre dos Elementos e Sede de Sangue/Heroísmo; os totens continuam manuais."
L["rm.tbc.shaman.elemental.wowhead.Name"] = "Elemental (Wowhead)"
L["rm.tbc.shaman.elemental.wowhead.Description"] = "O Elemental da Wowhead, uma alternativa à rotação integrada de Elemental da Icy Veins recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. No 70, Cadeia de Raios sempre que sair do tempo de recarga com Raios entre elas (durante a evolução de nível, só com Mestre dos Elementos ou Abstração), Choque Flamejante só em movimento, Choque Terreno para finalizar um alvo que morreria antes de um lançamento terminar. Os mesmos lembretes de totens, escudo e tempos de recarga da variante Icy Veins."
L["rm.tbc.shaman.enhancement.icyveins.Name"] = "Aperfeiçoamento (Icy Veins)"
L["rm.tbc.shaman.enhancement.icyveins.Description"] = "Aperfeiçoamento corpo a corpo do nível 1 ao 70, e o padrão para qualquer Xamã em que nenhuma outra rotação integrada se encaixe. Puxa com Raio à distância, interrompe com Choque Terreno, coloca Totem de Nova de Fogo e Totem de Magma contra três ou mais inimigos próximos, depois Ataque da Tempestade, Choque Terreno enquanto a penalidade do Ataque da Tempestade estiver ativa, Choque Flamejante em um alvo que vá sobreviver, Choque Terreno sempre que sair do tempo de recarga e Raio enquanto o alvo estiver fora de alcance. Lembretes separados: encantamentos de arma, Escudo de Água ou Escudo de Raios, Força da Terra, Fúria dos Ventos (em grupo) ou Graça do Ar (solo), Totem Calcinante em lutas longas, totens de água, Fúria Xamanística, Sede de Sangue/Heroísmo em chefes, Garra de Pedra e Elemental da Terra quando solo. Elemental do Fogo é um passo opcional que começa desativado. O posicionamento dos totens, Lobo Fantasma e as curas ficam com você."
L["rm.tbc.shaman.enhancement.simulator.Name"] = "Aperfeiçoamento (Wowhead & simulador)"
L["rm.tbc.shaman.enhancement.simulator.Description"] = "O modelo de raide do nível 70 para alternar totens, uma alternativa à rotação integrada de Aperfeiçoamento da Icy Veins recomendada, desativada por padrão: ative-a e desative aquela, ou aumente a prioridade dela. Ataque da Tempestade, intercalação do Totem de Nova de Fogo, Choque Flamejante sempre que tiver expirado e Choque Terreno como choque principal, com Raio só fora de alcance. Os lembretes alternam os Totens de Fúria dos Ventos e da Graça do Ar, mantêm o Totem Calcinante ativo, usam Fúria Xamanística quando a mana fica baixa e compartilham com a variante Icy Veins a manutenção de encantamentos de arma, escudo e totens."
L["rm.tbc.shaman.restoration.Name"] = "Restauração"
L["rm.tbc.shaman.restoration.Description"] = "Cura para a árvore de talentos Restauração, no seu alvo amigável (ou em você mesmo, sem alvo): Rapidez da Natureza e Onda Curativa ou Onda Curativa Menor em emergências, Curar Veneno e Curar Doença, Escudo da Terra no seu foco, Cura Encadeada quando três aliados próximos estão feridos, Onda Curativa nos demais casos. Com um alvo hostil, passa para Choque Flamejante e Raio para jogar solo. Lembretes: Escudo de Água, Escudo da Terra no seu foco (defina o tanque como foco), Vagalhão de Mana, Fonte de Mana e Força da Terra em grupo, Sede de Sangue/Heroísmo. A escolha de quem curar e de qual grau usar fica com você."
